pub fn refuseExactIndexedCacheForSave(reason: []const u8) bool {
    z3d.g_exact_indexed_save_promotion_refusal = reason;
    if (!builtin.is_test) {
        log.print("[meshdoc] exact indexed topology cache cannot restore resident v5 ids: {s}\n", .{reason});
    }
    return false;
}

pub fn promoteLogicalTopologyFromExactIndexedCacheForSave() bool {
    z3d.g_exact_indexed_save_promotion_refusal = "";
    if (model_source.renderCornerLogicalIds() != null) return true;
    const source = model_source.verts() orelse return z3d.refuseExactIndexedCacheForSave("no durable source geometry");
    const source_count = model_source.count();
    if (source_count == 0 or source_count % 3 != 0 or z3d.g_edit_count != source_count)
        return z3d.refuseExactIndexedCacheForSave("displayed/source shape mismatch");
    const source_len = @as(usize, source_count) * 8;
    if (source.len < source_len) return z3d.refuseExactIndexedCacheForSave("truncated durable source geometry");
    const indexed = if (z3d.g_indexed_edit_mesh) |*mesh| mesh else return z3d.refuseExactIndexedCacheForSave("no indexed cache");
    if (!indexed.has_explicit_logical_topology)
        return z3d.refuseExactIndexedCacheForSave("indexed cache was imported from anonymous soup");

    const face_count = source_count / 3;
    const face_parts = z3d.capturePartOfFaces();
    defer if (face_parts) |parts| std.heap.c_allocator.free(parts);
    if (!indexed.residentMetadataMatchesWithSemantics(
        face_count,
        model_source.faceGroups(),
        face_parts,
        model_source.faceMaterials(),
        model_source.faceSemanticRegions(),
        model_source.faceSemanticInstances(),
    )) return z3d.refuseExactIndexedCacheForSave("cached face metadata is stale");
    if (!indexed.residentPositionsMatch(source[0..source_len], face_count))
        return z3d.refuseExactIndexedCacheForSave("cached positions are stale");
    if (!indexed.residentRenderChannelsMatch(source[0..source_len], face_count))
        return z3d.refuseExactIndexedCacheForSave("cached normals or UVs are stale");

    const logical_rows = z3d.flattenedLogicalRows(indexed.render_triangles.items);
    const logical_vertex_count: u32 = @intCast(indexed.vertices.items.len);
    if (!meshdoc_format.logicalRowsValid(
        std.heap.c_allocator,
        source[0..source_len],
        logical_rows,
        logical_vertex_count,
        false,
    )) return z3d.refuseExactIndexedCacheForSave("cached ids do not validate against current positions");
    if (model_source.semanticTableJson()) |semantic_json| {
        const paths_resolve = model_source.semanticEdgePathsResolveInTopology(
            std.heap.c_allocator,
            semantic_json,
            logical_rows,
            logical_vertex_count,
            model_source.faceGroups(),
        ) catch return z3d.refuseExactIndexedCacheForSave("semantic edge table is invalid");
        if (!paths_resolve) return z3d.refuseExactIndexedCacheForSave("named semantic edges do not resolve");
    }
    if (!model_source.setLogicalTopology(logical_rows, logical_vertex_count))
        return z3d.refuseExactIndexedCacheForSave("logical topology allocation failed");
    if (!builtin.is_test) {
        log.print("[meshdoc] restored exact resident RJMD-v5 logical ids from the matching indexed cache before save\n", .{});
    }
    return true;
}

pub fn composeDocumentSnapshot(allocator: std.mem.Allocator, painted: bool) ?model_source.MeshDocSnapshot {
    const use_displayed = painted or z3d.g_save_displayed_projection;
    const visible = if (use_displayed) (z3d.g_edit_verts orelse return null) else (model_source.verts() orelse return null);
    const visible_count = if (use_displayed) z3d.g_edit_count else model_source.count();
    const visible_len = @as(usize, visible_count) * 8;
    if (visible.len < visible_len or visible_len % 24 != 0) return null;
    const displayed_colors = if (use_displayed) z3d.collectCurrentFaceColors() else null;
    defer if (displayed_colors) |colors| std.heap.c_allocator.free(colors);
    if (use_displayed and visible_len > 0 and displayed_colors == null) return null;
    const visible_blocks: usize = if (visible_len > 0) 1 else 0;
    if (visible_blocks == 0 and z3d.g_hidden_groups.items.len == 0) return null;
    const displayed_groups = if (use_displayed and visible_blocks == 1) z3d.captureFaceGroups() else null;
    defer if (displayed_groups) |groups| std.heap.c_allocator.free(groups);
    const displayed_materials = if (use_displayed and visible_blocks == 1) z3d.captureFaceMaterials(visible_count / 3) else null;
    defer if (displayed_materials) |materials| std.heap.c_allocator.free(materials);
    var displayed_semantics = if (use_displayed and visible_blocks == 1 and model_source.faceSemanticRegions() != null)
        z3d.captureFaceSemantics(visible_count / 3)
    else
        null;
    defer if (displayed_semantics) |*semantics| semantics.deinit();
    if (use_displayed and visible_blocks == 1 and (displayed_groups == null or displayed_materials == null)) return null;
    const visible_logical_ids: ?[]const u32 = if (model_source.renderCornerLogicalIds()) |rows| blk: {
        if (rows.len != visible_count) return null;
        break :blk rows;
    } else null;
    const blocks = allocator.alloc(model_source.MeshDocFaceBlock, z3d.g_hidden_groups.items.len + visible_blocks) catch return null;
    defer allocator.free(blocks);
    if (visible_blocks == 1) {
        blocks[0] = .{
            .verts = visible[0..visible_len],
            .groups = if (use_displayed) displayed_groups else model_source.faceGroups(),
            .materials = if (use_displayed) displayed_materials else model_source.faceMaterials(),
            .semantic_regions = if (displayed_semantics) |semantics| semantics.regions else model_source.faceSemanticRegions(),
            .semantic_instances = if (displayed_semantics) |semantics| semantics.instances else model_source.faceSemanticInstances(),
            .render_corner_logical_ids = visible_logical_ids,
            .colors = if (use_displayed) displayed_colors else model_source.colors(),
        };
    }
    for (z3d.g_hidden_groups.items, 0..) |hidden, index| {
        blocks[index + visible_blocks] = .{
            .verts = if (painted) hidden.verts else hidden.source_verts,
            .groups = hidden.groups,
            .materials = hidden.materials,
            .semantic_regions = hidden.semantic_regions,
            .semantic_instances = hidden.semantic_instances,
            .render_corner_logical_ids = hidden.logical_ids,
            .colors = hidden.colors,
        };
    }
    var snapshot = model_source.composeMeshDocSnapshot(allocator, blocks) catch return null;
    if (model_source.semanticTableJson()) |json| {
        snapshot.semantic_table_json = if (snapshot.dense_to_stable_logical_ids) |dense_to_stable|
            model_source.semanticTableForLogicalSnapshotAlloc(allocator, json, dense_to_stable) catch {
                snapshot.deinit(allocator);
                return null;
            }
        else
            allocator.dupe(u8, json) catch {
                snapshot.deinit(allocator);
                return null;
            };
        if (snapshot.semantic_table_json == null) {
            snapshot.deinit(allocator);
            return null;
        }
    }
    return snapshot;
}

/// Complete durable source document. Visibility is presentation state: hidden
/// triangles remain part of RJMD even though they are absent from the live draw mesh.
pub fn modelDocumentSnapshot(allocator: std.mem.Allocator) ?model_source.MeshDocSnapshot {
    if (model_source.renderCornerLogicalIds() == null) {
        if (z3d.g_indexed_edit_mesh) |*indexed| {
            if (indexed.has_explicit_logical_topology) {
                _ = z3d.promoteLogicalTopologyFromExactIndexedCacheForSave();
            }
        }
    }
    return z3d.composeDocumentSnapshot(allocator, false);
}

