pub fn recoverSemanticTableForSnapshotAlloc(
    allocator: std.mem.Allocator,
    json: []const u8,
    dense_to_stable_logical_ids: ?[]const u32,
) z3d.RecoveredSemanticTable {
    if (dense_to_stable_logical_ids) |dense_to_stable| {
        if (model_source.semanticTableForLogicalSnapshotAlloc(allocator, json, dense_to_stable)) |remapped| {
            return .{ .json = remapped, .affected_count = 0 };
        } else |_| {}
    }
    const recovered = mesh_edge_semantics.recoveryTableWithReportAlloc(
        allocator,
        json,
        true,
        false,
    ) catch return .{
        .json = null,
        .affected_count = z3d.fullSemanticTableLossCount(allocator, json),
    };
    return .{
        .json = recovered.json,
        .affected_count = recovered.removed_content_count,
    };
}

/// Recovery-only resident snapshot for the Lore panic lane. The strict model
/// document above remains the ordinary Save authority. If strict composition
/// rejects inconsistent auxiliary channels, this door still copies every
/// complete live and hidden triangle from native memory into an owned snapshot;
/// the Lore encoder can then persist a current-v5 geometry envelope instead of
/// inheriting Save's refusal.
pub fn modelRecoverySnapshotWithReceipt(allocator: std.mem.Allocator) ?z3d.ModelRecoverySnapshotResult {
    if (z3d.composeDocumentSnapshot(allocator, false)) |snapshot| return .{ .document = snapshot };

    const visible = visible_block: {
        if (model_source.verts()) |rows| {
            if (rows.len >= 24) break :visible_block rows;
        }
        if (z3d.g_edit_verts) |rows| {
            if (rows.len >= 24) break :visible_block rows;
        }
        break :visible_block null;
    };
    const blocks = allocator.alloc(model_source.MeshDocFaceBlock, z3d.g_hidden_groups.items.len + 1) catch return null;
    defer allocator.free(blocks);
    var block_count: usize = 0;
    if (visible) |rows| {
        const usable = rows.len - (rows.len % 24);
        if (usable > 0) {
            blocks[block_count] = .{
                .verts = rows[0..usable],
                .groups = model_source.faceGroups(),
                .materials = model_source.faceMaterials(),
                .semantic_regions = model_source.faceSemanticRegions(),
                .semantic_instances = model_source.faceSemanticInstances(),
                .render_corner_logical_ids = model_source.renderCornerLogicalIds(),
                .colors = model_source.colors(),
            };
            block_count += 1;
        }
    }
    for (z3d.g_hidden_groups.items) |hidden| {
        const usable = hidden.source_verts.len - (hidden.source_verts.len % 24);
        if (usable == 0) continue;
        blocks[block_count] = .{
            .verts = hidden.source_verts[0..usable],
            .groups = hidden.groups,
            .materials = hidden.materials,
            .semantic_regions = hidden.semantic_regions,
            .semantic_instances = hidden.semantic_instances,
            .render_corner_logical_ids = hidden.logical_ids,
            .colors = hidden.colors,
        };
        block_count += 1;
    }
    if (block_count == 0) return null;
    const composition = model_source.composeMeshDocRecoverySnapshotWithReport(allocator, blocks[0..block_count]) catch return null;
    var snapshot = composition.snapshot;
    var semantic_table_affected_count: u64 = 0;
    if (snapshot.semantic_regions != null) {
        if (model_source.semanticTableJson()) |json| {
            const recovered = z3d.recoverSemanticTableForSnapshotAlloc(
                allocator,
                json,
                snapshot.dense_to_stable_logical_ids,
            );
            snapshot.semantic_table_json = recovered.json;
            semantic_table_affected_count = recovered.affected_count;
        }
    } else if (model_source.semanticTableJson()) |json| {
        semantic_table_affected_count = z3d.fullSemanticTableLossCount(allocator, json);
    }
    return .{
        .document = snapshot,
        .semantic_table_affected_count = semantic_table_affected_count,
        .composition_report = composition.report,
    };
}

pub fn modelRecoverySnapshot(allocator: std.mem.Allocator) ?model_source.MeshDocSnapshot {
    const recovered = z3d.modelRecoverySnapshotWithReceipt(allocator) orelse return null;
    return recovered.document;
}

